<script setup lang="ts">
import {computed} from 'vue';import {RouterLink,RouterView,useRouter} from 'vue-router';import {useAuth} from '@/stores/auth'
const auth=useAuth(),router=useRouter()
const links=[['Dashboard','/dashboard','dashboard',['*']],['New sale','/sales','sales',['admin','manager','cashier']],['Receipts','/receipts','receipts',['admin','manager','cashier']],['Sales history','/sales-history','sales_history',['admin','manager']],['Products','/products','products',['admin','manager']],['Purchases','/purchases','purchases',['admin','manager']],['Repairs & Service','/repairs','repairs',['admin','manager','cashier']],['Suppliers','/suppliers','suppliers',['admin']],['Customer credits','/credits','credits',['admin','manager','cashier']],['Creditors','/creditors','creditors',['admin','manager']],['Expenses','/expenses','expenses',['admin','manager']],['Reports','/reports','reports',['admin','manager']],['Balance','/balance','balance',['admin','manager']],['Search','/search','search',['*']],['CRM','/crm','crm',['admin']],['Content','/cms','cms',['admin']],['Users','/users','users',['admin']],['Activity','/activity','activity',['admin']],['My account','/account','account',['admin','manager','cashier']],['Settings','/settings','settings',['admin']]] as const
const visible=computed(()=>links.filter(x=>auth.can(x[2] as any,x[3] as any)))
async function logout(){await auth.logout();await router.replace('/login')}
</script>
<template><div class="app-shell"><aside class="sidebar"><RouterLink to="/dashboard" class="brand"><img src="/logo.png" alt=""><span>Hybrid Shop</span></RouterLink><nav><RouterLink v-for="l in visible" :key="l[1]" :to="l[1]">{{l[0]}}</RouterLink></nav><div class="sidebar-foot"><b>{{auth.profile?.username}}</b><small>{{auth.profile?.role}}</small><button @click="logout">Sign out</button></div></aside><main class="main-area"><header class="mobile-head"><b>Hybrid Shop</b><button @click="logout">Sign out</button></header><RouterView/></main></div></template>
